DPSMateXSpellIcons = spellIcons

BabbleSpellX = {}

function BabbleSpellX:GetSpellIcon(spell)
	local icon = spellIcons[spell]
	if icon then
		return "Interface\\Icons\\" .. icon 
	end
	return nil
end

function BabbleSpellX:GetTranslation(spell)
	if translation[spell] then
		return translation[spell]
	end
	return spell
end

function BabbleSpellX:HasReverseTranslation(spell)
	if spellIcons[spell] then
		return true
	end
	return false
end

DPSMateX.BabbleSpellX = BabbleSpellX

